#define LED1 2
#define LED2 4
#define BUZZER 16
void setup() {
pinMode(LED1, OUTPUT);
pinMode(LED2, OUTPUT);
pinMode(BUZZER, OUTPUT);
}
void loop() {
// LED 1 menyala + buzzer bunyi
digitalWrite(LED1, HIGH);
digitalWrite(LED2, LOW);
tone(BUZZER, 1000); // frekuensi buzzer 1000 Hz
delay(1000);
noTone(BUZZER);
digitalWrite(LED1, LOW);
delay(200);
// LED 2 menyala + buzzer bunyi
digitalWrite(LED2, HIGH);
digitalWrite(LED1, LOW);
tone(BUZZER, 1500); // frekuensi berbeda
delay(1000);
noTone(BUZZER);
digitalWrite(LED2, LOW);
delay(200);
}
